import sys

def get_base_dir():
    if getattr(sys, 'frozen', False):
        # We are running in a bundle (PyInstaller)
        return os.path.dirname(sys.executable)
    else:
        # We are running in a normal Python environment
        # Because this file is in utils/, the base dir is its parent
        return os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

CONFIG_FILE = os.path.join(get_base_dir(), "config.json")

}

def load_config():
    if not os.path.exists(CONFIG_FILE):
        return {"hotkeys": DEFAULT_HOTKEYS, "options": DEFAULT_OPTIONS}

    try:
        with open(CONFIG_FILE, "r", encoding="utf-8") as f:
            config = json.load(f)

            # Merge with defaults in case new keys were added in later versions
            hotkeys = config.get("hotkeys", {})
            for k, v in DEFAULT_HOTKEYS.items():
                if k not in hotkeys:
                    hotkeys[k] = v

            options = config.get("options", {})
            for k, v in DEFAULT_OPTIONS.items():
                if k not in options:
                    options[k] = v

            config["hotkeys"] = hotkeys
            config["options"] = options
            return config
    except Exception as e:
        print(f"Failed to load config: {e}")
        return {"hotkeys": DEFAULT_HOTKEYS, "options": DEFAULT_OPTIONS}

def save_config(config_data):

        return {"hotkeys": DEFAULT_HOTKEYS, "options": DEFAULT_OPTIONS}

def save_config(config_data):
    try:
        with open(CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(config_data, f, indent=4, ensure_ascii=False)
        return True
    except Exception as e:
        print(f"Failed to save config: {e}")
        return False

