    from datetime import datetime
    filename = datetime.now().strftime("IMG_%Y%m%d_%H%M%S_%f.png")
    filepath = os.path.join(self.picture_save_path, filename)

    image.save(filepath, "PNG")

    self._manage_image_cache()

    return {
        "type": "image",
